declare(strict_types=1); require_once __DIR__.'/_guard.php'; dash_require('events'); dash_require_hq(); require_once __DIR__.'/../event-lib.php';if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:event-news-list.php');exit;}csrf_check();$pdo=dash_pdo();$id=(int)($_POST['id']??0);$eventId=(int)($_POST['event_id']??0);$title=trim((string)($_POST['title']??''));$content=trim((string)($_POST['content']??''));if(!$eventId||$title===''||$content==='')exit('رویداد، عنوان و متن خبر الزامی است.');$content=strip_tags($content,'<p><br><strong><em><h2><h3><ul><ol><li><a>');$slug=event_slug($title,$id);$image=null;if(!empty($_FILES['image']['name']))$image=event_asset($_FILES['image'],'event-news',['jpg','jpeg','png','webp'],12000000);$status=in_array($_POST['status']??'draft',['draft','published'],true)?$_POST['status']:'draft';if($id){$set='event_id=?,title=?,slug=?,excerpt=?,content=?,status=?';$params=[$eventId,$title,$slug,trim((string)($_POST['excerpt']??'')),$content,$status];if($image){$set.=',image=?';$params[]=$image;}$params[]=$id;$pdo->prepare("UPDATE event_news SET $set WHERE id=?")->execute($params);}else{$pdo->prepare('INSERT INTO event_news(event_id,title,slug,excerpt,content,image,status,published_at,created_by)VALUES(?,?,?,?,?,?,?,?,?)')->execute([$eventId,$title,$slug,trim((string)($_POST['excerpt']??'')),$content,$image,$status,$status==='published'?date('Y-m-d H:i:s'):null,(int)(dash_user()['id']??0)]);}header('Location:event-news-list.php?event_id='.$eventId);
